Command `python3 - <<'PY'
import struct, math

def to_double_bits(x):
    return struct.unpack('<Q', struct.pack('<d', x))[0]

def from_double_bits(b):
    return struct.unpack('<d', struct.pack('<Q', b))[0]

# mimic C: a = (double)beg_int ; b = end_double
# capacity = int(b - a) + 1   (C truncation toward zero)
# inclusive loop: while a <= b: i++; a += 1.0
# exclusive loop: while a < b: i++; a += 1.0
def simulate(beg, end, excl):
    a = float(beg)   # (mrb_float)mrb_integer(beg)
    b = end
    if a > b:
        return None
    cap = int(b - a) + 1   # C (mrb_int) truncation toward zero; b-a positive
    i = 0
    if excl:
        while a < b:
            i += 1
            a += 1.0
            if i > cap + 100:  # safety
                break
    else:
        while a <= b:
            i += 1
            a += 1.0
            if i > cap + 100:
                break
    return cap, i

# Search: beg integers, end doubles. We want i > cap (overflow).
# Try begs around powers of two and ends around beg + small.
found = []
# enumerate end as doubles near beg + k for small k, with beg large
for exp in range(40, 54):
    base = 2**exp
    for beg in [base-3, base-2, base-1, base, base+1, base+2, base+3, base+4]:
        a0 = float(beg)
        # try ends = a0 + small doubles
        for k in range(0, 6):
            # try end = a0 + k (as float math) and neighbors
            for delta_bits in range(-4, 5):
                end = from_double_bits(to_double_bits(a0 + k) + delta_bits) if a0+k == a0+k else a0+k
                for excl in [False, True]:
                    r = simulate(beg, end, excl)
                    if r and r[1] > r[0]:
                        found.append((beg, end, repr(end), excl, r))
print("found count:", len(found))
for f in found[:30]:
    print(f)
